<script setup lang="ts">
import {ref,computed,onMounted,watch,nextTick} from 'vue';import ProfessionalCard from './components/ProfessionalCard.vue';import {api,ApiError,unreachable} from './api';import {useSession} from './stores/session';import {useLive} from './composables/useLive';import {useExperiment} from './stores/experiment';import {useOutbox} from './stores/outbox';import {specialties,dateLabel,timeLabel,type Professional,type Slot,type Page,type Appointment,type Notice} from './types';
const session=useSession(),live=useLive(),personalLive=useLive(),experiment=useExperiment(),outbox=useOutbox();
// Hors ligne : réseau coupé, ou serveur injoignable et données servies depuis le cache de l'appareil.
const online=ref(navigator.onLine),cachedData=ref(false),pendingNotice=ref('');
const pendingMine=computed(()=>outbox.items.filter(i=>i.userId===session.user?.id));
const view=ref<'search'|'appointments'>('search'),loading=ref(false),busy=ref(false),error=ref(''),success=ref('');
const q=ref(''),city=ref(''),specialty=ref(''),page=ref(0),total=ref(0),doctors=ref<Professional[]>([]),slots=ref<Record<number,Slot[]>>({});
const appointments=ref<Appointment[]>([]),notices=ref<Notice[]>([]),showNotices=ref(false),profile=ref<Professional|null>(null);
const authOpen=ref(false),register=ref(false),email=ref(''),password=ref(''),name=ref(''),authError=ref(''),fieldErrors=ref<Record<string,string>>({});
const chosen=ref<{professional:Professional;slot:Slot}|null>(null),moveId=ref<number|null>(null),history=ref<{action:string;createdAt:string}[]|null>(null),cancelId=ref<number|null>(null);
// Accessibilité (RGAA 8.6, 12.6) : chaque vue a son titre d'onglet, et le focus va sur son h1 quand elle change.
const titles={search:'Trouver un praticien',appointments:'Mes rendez-vous'};
document.title=`${titles[view.value]} · MediSlot`;
const focusH1=()=>nextTick(()=>document.querySelector<HTMLElement>('main h1')?.focus());
watch(view,v=>{document.title=`${titles[v]} · MediSlot`;focusH1();});
// Fenêtre modale (RGAA 7.3, 12.8) : le focus entre par le titre, reste dans la fenêtre, et revient d'où il venait
// (ou sur le h1 si cet élément a disparu). L'origine n'est mémorisée qu'à l'ouverture.
const modal=ref<HTMLElement|null>(null);let priorFocus:HTMLElement|null=null;
const modalKind=computed(()=>authOpen.value?'auth':chosen.value?'confirm':profile.value?'profile':history.value?'history':cancelId.value!==null?'cancel':null);
watch(modalKind,(kind,old)=>{
 if(kind&&!old)priorFocus=document.activeElement as HTMLElement;
 if(kind)nextTick(()=>modal.value?.querySelector<HTMLElement>('#modal-title')?.focus());
 else if(old)nextTick(()=>{(priorFocus?.isConnected?priorFocus:document.querySelector<HTMLElement>('main h1'))?.focus();priorFocus=null;});
});
function closeModal(){if(busy.value)return;authOpen.value=false;chosen.value=null;profile.value=null;history.value=null;cancelId.value=null;}
const FOCUSABLE='button,input,select,textarea,a[href],summary,[tabindex]:not([tabindex="-1"])';
function trap(e:KeyboardEvent){if(e.key==='Escape')closeModal();if(e.key==='Tab'&&modal.value){const a=[...modal.value.querySelectorAll<HTMLElement>(FOCUSABLE)].filter(el=>!el.closest('[hidden]'));const first=a[0],last=a[a.length-1];if(!a.includes(document.activeElement as HTMLElement)){e.preventDefault();(e.shiftKey?last:first)?.focus()}else if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}
let searchGeneration=0;
async function search(reset=false){if(reset)page.value=0;const generation=++searchGeneration;loading.value=true;error.value='';try{const result=await api<Page<Professional>>('/professionals?'+new URLSearchParams({q:q.value,city:city.value,specialty:specialty.value,page:String(page.value),size:'6'}));if(generation!==searchGeneration)return;doctors.value=result.items;total.value=result.total;await loadSlots();}catch(e){error.value=message(e)}finally{if(generation===searchGeneration)loading.value=false}}
async function loadSlots(){const entries=await Promise.all(doctors.value.map(async p=>[p.id,await api<Slot[]>(`/professionals/${p.id}/slots`)] as const));slots.value=Object.fromEntries(entries);}
// Exposition A/B : après chaque rendu des créneaux, si au moins un bouton de réservation est affiché.
watch([slots,()=>experiment.variant],()=>{experiment.exposeIfAvailable()});
function message(e:unknown){return e instanceof TypeError?'Connexion impossible. Vérifiez le réseau puis réessayez.':e instanceof Error?e.message:'Une erreur est survenue.'}
async function refreshAppointments(){if(!session.user)return;appointments.value=await api<Appointment[]>('/appointments');}
async function refreshNotices(){if(session.user)notices.value=await api<Notice[]>('/notifications');}
function choose(professional:Professional,slot:Slot){success.value='';error.value='';profile.value=null;chosen.value={professional,slot};if(!session.user)openAuth();}
// Erreurs de formulaire (RGAA 11.10, 11.11) : chaque message du serveur va sous son champ, et le focus sur le premier champ fautif.
async function authenticate(){if(busy.value)return;busy.value=true;authError.value='';fieldErrors.value={};try{if(register.value)await api('/register',{method:'POST',body:JSON.stringify({name:name.value,email:email.value,password:password.value})});await session.login(email.value,password.value);authOpen.value=false;password.value='';await refreshAppointments();}catch(e){
 if(e instanceof ApiError&&Object.keys(e.fields).length)fieldErrors.value=e.fields;else if(e instanceof ApiError&&e.status===409&&register.value)fieldErrors.value={email:e.message};else authError.value=message(e);
 nextTick(()=>modal.value?.querySelector<HTMLElement>('[aria-invalid="true"]')?.focus());
}finally{busy.value=false}}
const describedBy=(field:string,hint?:string)=>[hint,fieldErrors.value[field]?`err-${field}`:''].filter(Boolean).join(' ')||undefined;
function queueBooking(){
 const c=chosen.value!;outbox.enqueue({userId:session.user!.id,slotId:c.slot.id,professionalName:c.professional.name,startsAt:c.slot.startsAt,measured:experiment.measured});
 success.value='';pendingNotice.value=`Pas de réseau : votre demande pour le ${dateLabel(c.slot.startsAt)} à ${timeLabel(c.slot.startsAt)} avec ${c.professional.name} sera envoyée dès le retour de la connexion. Elle n’est pas encore confirmée.`;
 chosen.value=null;view.value='appointments';
}
async function flushOutbox(){
 if(!session.user||!pendingMine.value.length)return;
 const results=await outbox.flush(session.user.id);if(!results.length)return;
 const when=(r:{item:{startsAt:string;professionalName:string}})=>`du ${dateLabel(r.item.startsAt)} à ${timeLabel(r.item.startsAt)} avec ${r.item.professionalName}`;
 const ok=results.filter(r=>r.outcome==='confirmed'),ko=results.filter(r=>r.outcome!=='confirmed');
 pendingNotice.value='';
 if(ok.length)success.value=ok.map(r=>`Votre rendez-vous ${when(r)} est confirmé.`).join(' ');
 if(ko.length)error.value=ko.map(r=>r.outcome==='taken'?`Le créneau ${when(r)} a été pris pendant que vous étiez hors ligne. Choisissez-en un autre.`:r.outcome==='login'?'Reconnectez-vous pour envoyer votre demande en attente.':`La demande ${when(r)} a été refusée : ${r.message??'erreur inconnue'}.`).join(' ');
 // Session perdue (expirée, ou serveur redémarré) : on le montre et on propose de se reconnecter ; la demande reste en file
 // et part dès la connexion (watch sur session.user).
 if(results.some(r=>r.outcome==='login')){session.user=null;personalLive.close();openAuth();authError.value='Reconnectez-vous pour envoyer votre demande en attente.';return;}
 await Promise.allSettled([refreshAppointments(),refreshNotices(),loadSlots()]);
}
async function confirm(){if(!chosen.value||busy.value)return;busy.value=true;error.value='';
 if(!navigator.onLine&&!moveId.value){queueBooking();busy.value=false;return;}
 try{await api(moveId.value?`/appointments/${moveId.value}`:'/appointments',{method:moveId.value?'PATCH':'POST',headers:moveId.value?{}:experiment.measureHeaders(),body:JSON.stringify({slotId:chosen.value.slot.id})});success.value=moveId.value?'Votre rendez-vous a été déplacé.':'Votre rendez-vous est confirmé.';chosen.value=null;moveId.value=null;await refreshAppointments();await refreshNotices();await loadSlots();view.value='appointments';}catch(e){if(unreachable(e)&&!moveId.value){queueBooking();return;}error.value=unreachable(e)?'Connexion impossible : le déplacement nécessite le réseau. Réessayez une fois connecté.':message(e);if(e instanceof ApiError&&e.status===409){chosen.value=null;await loadSlots();}}finally{busy.value=false}}
async function cancel(){if(cancelId.value===null||busy.value)return;busy.value=true;try{await api(`/appointments/${cancelId.value}/cancel`,{method:'POST'});cancelId.value=null;success.value='Votre rendez-vous a été annulé.';await refreshAppointments();await loadSlots();await refreshNotices();}catch(e){error.value=message(e)}finally{busy.value=false}}
async function move(a:Appointment){moveId.value=a.id;q.value=a.professionalName;city.value='';specialty.value='';view.value='search';await search(true);success.value='Choisissez un nouveau créneau. Votre réservation actuelle reste conservée jusqu’à confirmation.';}
async function showHistory(id:number){try{history.value=await api(`/appointments/${id}/history`)}catch(e){error.value=message(e)}}
async function logout(){try{await session.logout();const dropped=pendingMine.value.length;outbox.clear();if('caches' in window)for(const k of await caches.keys())if(k.startsWith('medislot-api'))await caches.delete(k);if(dropped)success.value='Vous êtes déconnecté. Les demandes en attente sur cet appareil ont été supprimées.';personalLive.close();notices.value=[];appointments.value=[];showNotices.value=false;view.value='search';moveId.value=null;}catch(e){error.value=message(e)}}
function openAuth(){authOpen.value=true;authError.value='';fieldErrors.value={};register.value=false;}
function toggleRegister(){register.value=!register.value;authError.value='';fieldErrors.value={};}
function myAppointments(){if(!session.user){openAuth();return;}view.value='appointments';refreshAppointments().catch(e=>error.value=message(e));}
const when=(a:{startsAt:string;professionalName:string})=>`du ${dateLabel(a.startsAt)} à ${timeLabel(a.startsAt)} avec ${a.professionalName}`;
watch(()=>session.user, user=>{personalLive.close();if(user){flushOutbox();refreshNotices().catch(()=>{});personalLive.connect('/api/notifications/events',()=>{refreshNotices().catch(()=>{});refreshAppointments().catch(()=>{})},'notifications-changed')}});
window.addEventListener('online',()=>{online.value=true;flushOutbox();});
// Filet de sécurité : serveur revenu sans changement d'état réseau ni reconnexion SSE observée.
setInterval(()=>{if(pendingMine.value.length&&navigator.onLine)flushOutbox();},15000);window.addEventListener('offline',()=>{online.value=false;});
window.addEventListener('medislot:cached-data',()=>{cachedData.value=true;});window.addEventListener('medislot:fresh-data',()=>{cachedData.value=false;});
onMounted(async()=>{experiment.load();await search();try{await session.load()}catch(e){error.value=message(e)}live.connect('/api/events',()=>{loadSlots().catch(()=>{});flushOutbox();});});
</script>
<template>
 <a href="#main" class="skip">Aller au contenu</a>
 <header class="header"><button class="brand" @click="view='search';moveId=null">MediSlot<span class="brand-dot">.</span></button><nav aria-label="Navigation principale"><button :class="{active:view==='search'}" :aria-current="view==='search'?'page':undefined" @click="view='search'">Trouver un praticien</button><button :class="{active:view==='appointments'}" :aria-current="view==='appointments'?'page':undefined" @click="myAppointments">Mes rendez-vous</button><button v-if="session.user" @click="showNotices=!showNotices" :aria-expanded="showNotices">Notifications <span class="count">{{notices.length}}</span></button><button v-if="!session.user" class="login" @click="openAuth">Se connecter</button><button v-else class="login" @click="logout">{{session.user.name.split(' ')[0]}} · Déconnexion</button></nav></header>
 <main id="main" tabindex="-1">
 <section v-if="view==='search'" class="hero"><div class="hero-inner"><p class="eyebrow">VOTRE PROCHAIN RENDEZ-VOUS</p><h1 tabindex="-1">Trouvez le bon praticien.<br>Prenez un moment pour vous.</h1><p class="hero-copy">Un professionnel près de chez vous, au créneau qui vous convient.</p><form class="searchbar" role="search" @submit.prevent="search(true)"><label><span>Nom du praticien</span><input v-model="q" placeholder="Nom, praticien…" autocomplete="off"></label><label><span>Spécialité</span><select v-model="specialty"><option value="">Toutes les spécialités</option><option v-for="(label,key) in specialties" :key="key" :value="key">{{label}}</option></select></label><label><span>Ville</span><input v-model="city" placeholder="Paris, Lyon…" autocomplete="address-level2"></label><button type="submit" :disabled="loading">{{loading?'Recherche…':'Rechercher'}} <span aria-hidden="true">→</span></button></form><div class="hero-bottom"><span>Des créneaux visibles en quelques clics</span><span class="live" :class="{offline:!live.connected.value}"><i></i>{{live.connected.value?'Disponibilités en direct':'Reconnexion du direct…'}}</span></div></div></section>
 <div class="main">
  <div v-if="showNotices&&session.user" class="notices"><div class="section-title"><h2>Vos notifications</h2><button class="text-button" @click="showNotices=false">Fermer</button></div><p v-if="!notices.length">Aucune notification pour le moment.</p><p v-for="n in notices" :key="n.id">{{n.message}} <small>{{dateLabel(n.createdAt)}}</small></p></div>
  <!-- Messages dynamiques (RGAA 7.5) : les régions existent toujours, seul leur contenu apparaît, pour être lues à coup sûr. -->
  <div role="status"><p v-if="!online||cachedData" class="alert offline">Vous êtes hors ligne. Les informations affichées sont les dernières enregistrées sur cet appareil et peuvent avoir changé. Une réservation demandée maintenant sera envoyée au retour de la connexion.</p><p v-if="pendingNotice" class="alert offline">{{pendingNotice}}</p><p v-if="success" class="alert success">{{success}}</p></div>
  <div role="alert"><p v-if="error&&modalKind!=='confirm'" class="alert error">{{error}} <button class="text-button" @click="search()">Réessayer</button></p></div>
  <template v-if="view==='search'"><div class="section-title"><div><p class="eyebrow dark">VOTRE RECHERCHE</p><h2>{{total}} praticien{{total>1?'s':''}} à découvrir</h2></div><span class="subtle">Rendez-vous au cabinet</span></div>
   <div v-if="moveId" class="move-banner">Déplacement du rendez-vous n° {{moveId}} <button class="text-button" @click="moveId=null;success=''">Abandonner le déplacement</button></div>
   <div role="status"><div v-if="loading" class="loading">Nous recherchons vos prochains créneaux…</div></div><div v-if="!loading&&!doctors.length" class="empty"><h3>Aucun praticien ne correspond à cette recherche</h3><p>Essayez une autre ville ou une spécialité différente.</p><button class="primary" @click="q='';city='';specialty='';search(true)">Voir tous les praticiens</button></div>
   <div v-else-if="!loading" class="results"><div class="cards"><ProfessionalCard v-for="p in doctors" :key="p.id" :professional="p" :slots="slots[p.id]||[]" :cta-label="experiment.label" :cta-ready="experiment.variant!==null" @choose="choose" @profile="profile=$event"/></div><aside class="help"><span class="help-icon" aria-hidden="true">+</span><h2>Votre rendez-vous,<br>en toute simplicité.</h2><ol><li>Choisissez votre praticien.</li><li>Sélectionnez un créneau.</li><li>Retrouvez la confirmation dans votre espace.</li></ol><hr><p>Un changement de programme ? Vous pouvez déplacer ou annuler votre rendez-vous depuis votre espace.</p><p class="demo-note">Démonstration pédagogique.<br>Praticiens et données fictifs.</p></aside></div>
   <nav v-if="total>6" class="pagination" aria-label="Pages de résultats"><button :disabled="page===0" @click="page--;search()">Précédent</button><span>Page {{page+1}}</span><button :disabled="(page+1)*6>=total" @click="page++;search()">Suivant</button></nav>
  </template>
  <template v-else><div class="section-title"><div><p class="eyebrow dark">VOTRE ESPACE</p><h1 tabindex="-1">Mes rendez-vous</h1></div><button class="primary" @click="view='search'">Prendre rendez-vous</button></div><p v-if="!appointments.length&&!pendingMine.length" class="empty">Vous n’avez pas encore de rendez-vous.</p><article v-for="p in pendingMine" :key="p.key" class="appointment pending"><div class="appointment-date"><strong>{{dateLabel(p.startsAt)}}</strong><span>{{timeLabel(p.startsAt)}}</span></div><div class="appointment-person"><h2>{{p.professionalName}}</h2><p>Demandée hors ligne, envoyée au retour de la connexion.</p><span class="status waiting">En attente d’envoi · non confirmé</span></div><div class="appointment-actions"><button class="danger-link" @click="outbox.remove(p.key)">Retirer la demande<span class="sr-only"> {{when(p)}}</span></button></div></article><article v-for="a in appointments" :key="a.id" class="appointment"><div class="appointment-date"><strong>{{dateLabel(a.startsAt)}}</strong><span>{{timeLabel(a.startsAt)}}</span></div><div class="appointment-person"><h2>{{a.professionalName}}</h2><p>{{specialties[a.specialty]}} · {{a.city}}</p><span class="status" :class="{cancelled:a.status==='CANCELLED'}">{{a.status==='CONFIRMED'?'Confirmé':'Annulé'}}</span></div><div class="appointment-actions"><button v-if="a.status==='CONFIRMED'" @click="move(a)">Déplacer<span class="sr-only"> le rendez-vous {{when(a)}}</span></button><button v-if="a.status==='CONFIRMED'" class="danger-link" @click="cancelId=a.id">Annuler<span class="sr-only"> le rendez-vous {{when(a)}}</span></button><button class="text-button" @click="showHistory(a.id)">Historique<span class="sr-only"> du rendez-vous {{when(a)}}</span></button></div></article></template>
 </div></main><footer><span class="brand footer-brand">MediSlot.</span><p>Votre parcours de soins, simplement.</p><small>Application de formation · Données fictives · Horaires Europe/Paris</small></footer>
 <div v-if="modalKind" class="overlay" @click.self="closeModal"><section ref="modal" class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" @keydown="trap"><button class="close" aria-label="Fermer" @click="closeModal">×</button>
  <template v-if="authOpen"><p class="eyebrow dark">VOTRE ESPACE MEDISLOT</p><h2 id="modal-title" tabindex="-1">{{register?'Créer votre compte':'Heureux de vous retrouver'}}</h2><p class="subtle">Connectez-vous pour confirmer et retrouver vos rendez-vous.</p><form class="auth-form" novalidate @submit.prevent="authenticate"><p class="form-note">Tous les champs sont obligatoires.</p>
   <label v-if="register">Votre nom<input v-model="name" maxlength="120" autocomplete="name" :aria-invalid="!!fieldErrors.name" :aria-describedby="describedBy('name')"></label><p v-if="register" id="err-name" class="field-error"><template v-if="fieldErrors.name">Erreur : {{fieldErrors.name}}</template></p>
   <label>Adresse e-mail<input v-model="email" type="email" autocomplete="email" :aria-invalid="!!fieldErrors.email" :aria-describedby="describedBy('email')"></label><p id="err-email" class="field-error"><template v-if="fieldErrors.email">Erreur : {{fieldErrors.email}}</template></p>
   <label>Mot de passe<input v-model="password" type="password" maxlength="72" :autocomplete="register?'new-password':'current-password'" :aria-invalid="!!fieldErrors.password" :aria-describedby="describedBy('password',register?'pw-hint':undefined)"></label><p v-if="register" id="pw-hint" class="form-note">12 caractères au moins.</p><p id="err-password" class="field-error"><template v-if="fieldErrors.password">Erreur : {{fieldErrors.password}}</template></p>
   <div role="alert"><p v-if="authError" class="error-text">{{authError}}</p></div><button class="primary" :aria-disabled="busy">{{busy?'Connexion…':register?'Créer mon compte':'Se connecter'}}</button></form><button class="text-button" @click="toggleRegister">{{register?'J’ai déjà un compte':'Créer un compte'}}</button><details class="demo-credentials"><summary>Compte de démonstration</summary><p>patient@medislot.test<br>MediSlot-demo-2026!</p></details></template>
  <template v-else-if="chosen"><p class="eyebrow dark">DERNIÈRE ÉTAPE</p><h2 id="modal-title" tabindex="-1">Confirmer votre rendez-vous</h2><div class="booking-summary"><h3>{{chosen.professional.name}}</h3><p>{{specialties[chosen.professional.specialty]}}</p><strong>{{dateLabel(chosen.slot.startsAt)}} à {{timeLabel(chosen.slot.startsAt)}}</strong><p>{{chosen.professional.address}}, {{chosen.professional.city}}</p></div><p class="subtle">Le créneau sera réservé après confirmation du serveur. Une autre personne peut encore le sélectionner entre-temps.</p><div role="alert"><p v-if="error" class="error-text">{{error}}</p></div><button class="primary wide" :aria-disabled="busy" @click="confirm">{{busy?'Confirmation…':moveId?'Confirmer le déplacement':'Confirmer le rendez-vous'}}</button></template>
  <template v-else-if="profile"><p class="eyebrow dark">VOTRE PRATICIEN</p><h2 id="modal-title" tabindex="-1">{{profile.name}}</h2><p class="specialty">{{specialties[profile.specialty]}}</p><p>{{profile.bio}}</p><h3>Le cabinet</h3><p>{{profile.address}}, {{profile.city}}</p><h3>Consultation</h3><p>{{profile.fee}} € · 30 minutes · Au cabinet</p><button class="primary wide" @click="profile=null">Voir les disponibilités</button></template>
  <template v-else-if="history"><h2 id="modal-title" tabindex="-1">Historique du rendez-vous</h2><ol class="timeline"><li v-for="(h,i) in history" :key="i"><strong>{{({CREATED:'Réservation confirmée',RESCHEDULED:'Rendez-vous déplacé',CANCELLED:'Rendez-vous annulé'} as Record<string,string>)[h.action]||h.action}}</strong><p>{{dateLabel(h.createdAt)}} à {{timeLabel(h.createdAt)}}</p></li></ol></template>
  <template v-else-if="cancelId!==null"><h2 id="modal-title" tabindex="-1">Annuler ce rendez-vous ?</h2><p>Le créneau sera remis à disposition. Vous pourrez prendre un autre rendez-vous quand vous le souhaitez.</p><button class="primary wide" :aria-disabled="busy" @click="cancel">Confirmer l’annulation</button><button class="text-button" @click="cancelId=null">Conserver mon rendez-vous</button></template>
 </section></div>
</template>
